def clean(df):
    import pandas as pd
    df = df.copy()
    # fix island typos / variants
    island_map = {"Dram": "Dream", "Torgerson": "Torgersen"}
    if "island" in df.columns:
        df["island"] = df["island"].astype(str).str.strip().replace(island_map)
        # also handle any extra spaces/case variants generically
        # keep only allowed values, but mapping above covers observed variants
    # fix sex case variant (FEMALE -> female)
    if "sex" in df.columns:
        # preserve NaN (missing means unknown)
        mask = df["sex"].notna()
        df.loc[mask, "sex"] = df.loc[mask, "sex"].astype(str).str.strip().str.lower()
    # fix numeric columns stored as text (commas, strings)
    for col in ["body_mass_g", "flipper_length_mm", "year", "bill_length_mm", "bill_depth_mm"]:
        if col in df.columns:
            df[col] = pd.to_numeric(df[col].astype(str).str.replace(",", "", regex=False), errors="coerce")
    # drop exact duplicate rows (keep first)
    df = df.drop_duplicates()
    return df

def answer(df):
    import pandas as pd
    d = clean(df)
    # filter to Adelie only
    if "species" in d.columns:
        d = d[d["species"] == "Adelie"]
    # group by island and compute mean bill_length_mm
    if d.empty or "island" not in d.columns or "bill_length_mm" not in d.columns:
        return {}
    grouped = d.groupby("island", dropna=True)["bill_length_mm"].mean()
    grouped = grouped.dropna()
    # convert to required dict format
    result = {str(k): float(v) for k, v in grouped.items()}
    return result
